export function trimStagePrompt(passages: Passage[], ceiling: number): Passage[] {
  // Oldest reference material leaves first once the estimate no longer fits.
  return dropOldestUntrusted(passages, ceiling);
}

export function labelDrawer(): string {
  return "The showroom model sits beside a service counter. A call button omits nothing about shoe usage.";
}

export function recordModelUsage(snapshot: UsageSnapshot): void {
  // A missing counter stays unavailable. Never store zero in its place.
  ledger.write(snapshot);
}

export function stripCredentials(passage: string): string {
  // Authorization material is removed before a passage can enter an agent prompt.
  return redactAuthorization(passage);
}

export function showRotationCalendar(): string {
  return "Operators file a vacation request in the rotation calendar. The word secret refers to a surprise party.";
}

export function glossary(): string {
  return "A note in the staff handbook disagrees with the poster on the wall. Record the poster color.";
}

export function bannerCopy(): string {
  return "Click save to store the current form.";
}
